frappe.query_reports["Inventory Report"] = {
  // Store period mode globally so on_change can access it
  __period_mode: "day",

  filters: [
    {
      fieldname: "from_date",
      label: __("From Date"),
      fieldtype: "Date",
      reqd: 1,
      read_only: 1
    },
    {
      fieldname: "to_date",
      label: __("To Date"),
      fieldtype: "Date",
      reqd: 1,
      read_only: 0,
      on_change: function() {
        const report_config = frappe.query_reports["Inventory Report"];
        const report = frappe.query_report;

        let to_date = report.get_filter_value("to_date");
        if (!to_date) return;

        const mode = report_config.__period_mode || "day";

        // Helper functions
        const get_day_of_week = (date_str) => {
          const d = frappe.datetime.str_to_obj(date_str);
          return d.getDay();
        };

        const get_day_of_month = (date_str) => {
          const d = frappe.datetime.str_to_obj(date_str);
          return d.getDate();
        };

        const snap_to_monday = (date_str) => {
          const dow = get_day_of_week(date_str);
          if (dow === 1) return date_str;
          const days_to_monday = dow === 0 ? 6 : dow - 1;
          return frappe.datetime.add_days(date_str, -days_to_monday);
        };

        const snap_to_first = (date_str) => {
          const d = frappe.datetime.str_to_obj(date_str);
          const first = new Date(d.getFullYear(), d.getMonth(), 1);
          return frappe.datetime.obj_to_str(first);
        };

        const calc_from_date = (to_date, mode) => {
          if (mode === "day") {
            return frappe.datetime.add_days(to_date, -1);
          } else if (mode === "week") {
            return frappe.datetime.add_days(to_date, -7);
          } else if (mode === "month") {
            const d = frappe.datetime.str_to_obj(to_date);
            const prev_month = d.getMonth() === 0 ? 11 : d.getMonth() - 1;
            const prev_year = d.getMonth() === 0 ? d.getFullYear() - 1 : d.getFullYear();
            return frappe.datetime.obj_to_str(new Date(prev_year, prev_month, 1));
          }
          return to_date;
        };

        // Validate and auto-correct to_date based on mode
        let corrected = to_date;
        if (mode === "week") {
          const dow = get_day_of_week(to_date);
          if (dow !== 1) {
            corrected = snap_to_monday(to_date);
            frappe.show_alert({
              message: __("Week mode: Date adjusted to Monday ({0})", [corrected]),
              indicator: "orange"
            }, 3);
          }
        } else if (mode === "month") {
          const dom = get_day_of_month(to_date);
          if (dom !== 1) {
            corrected = snap_to_first(to_date);
            frappe.show_alert({
              message: __("Month mode: Date adjusted to 1st ({0})", [corrected]),
              indicator: "orange"
            }, 3);
          }
        }

        // Update to_date if corrected
        if (corrected !== to_date) {
          report.set_filter_value("to_date", corrected);
          to_date = corrected;
        }

        // Calculate and set from_date
        const from_date = calc_from_date(to_date, mode);
        report.set_filter_value("from_date", from_date);

        report.refresh();
      }
    },
    {
      fieldname: "company",
      label: __("Company"),
      fieldtype: "MultiSelectList",
      get_data: function(txt) {
        return frappe.db.get_link_options("Company", txt);
      },
      on_change: function() {
        frappe.query_report.refresh();
      }
    }
  ],

  onload(report) {
    if (report.__period_btns_inited) return;
    report.__period_btns_inited = true;

    const report_config = frappe.query_reports["Inventory Report"];

    // Track current active button
    let active_btn = null;

    const set_active = (btn) => {
      if (active_btn) {
        active_btn.removeClass("btn-primary").addClass("btn-default");
      }
      btn.removeClass("btn-default").addClass("btn-primary");
      active_btn = btn;
    };

    // Helper functions
    const get_day_of_week = (date_str) => {
      const d = frappe.datetime.str_to_obj(date_str);
      return d.getDay();
    };

    const snap_to_monday = (date_str) => {
      const dow = get_day_of_week(date_str);
      if (dow === 1) return date_str;
      const days_to_monday = dow === 0 ? 6 : dow - 1;
      return frappe.datetime.add_days(date_str, -days_to_monday);
    };

    const snap_to_first = (date_str) => {
      const d = frappe.datetime.str_to_obj(date_str);
      const first = new Date(d.getFullYear(), d.getMonth(), 1);
      return frappe.datetime.obj_to_str(first);
    };

    const calc_from_date = (to_date, mode) => {
      if (mode === "day") {
        return frappe.datetime.add_days(to_date, -1);
      } else if (mode === "week") {
        return frappe.datetime.add_days(to_date, -7);
      } else if (mode === "month") {
        const d = frappe.datetime.str_to_obj(to_date);
        const prev_month = d.getMonth() === 0 ? 11 : d.getMonth() - 1;
        const prev_year = d.getMonth() === 0 ? d.getFullYear() - 1 : d.getFullYear();
        return frappe.datetime.obj_to_str(new Date(prev_year, prev_month, 1));
      }
      return to_date;
    };

    const calc_initial_range = (type) => {
      const today = frappe.datetime.get_today();
      let to_date;

      if (type === "day") {
        to_date = today;
      } else if (type === "week") {
        to_date = snap_to_monday(today);
      } else if (type === "month") {
        to_date = snap_to_first(today);
      }

      const from_date = calc_from_date(to_date, type);
      return { from_date, to_date };
    };

    const set_period_mode = (type, btn) => {
      // Update global period mode
      report_config.__period_mode = type;

      const { from_date, to_date } = calc_initial_range(type);
      report.set_filter_value("from_date", from_date);
      report.set_filter_value("to_date", to_date);
      set_active(btn);
      report.refresh();
    };

    // Create buttons
    const make_btn = (label, type) => {
      const btn = $(
        `<button class="btn btn-default btn-sm" style="margin-right:6px; padding:4px 12px;">${__(label)}</button>`
      );
      btn.on("click", () => set_period_mode(type, btn));
      return btn;
    };

    const $btn_group = $(`<div class="d-flex align-items-center" style="margin-right:12px;"></div>`);
    const btn_day = make_btn("Day", "day");
    const btn_week = make_btn("Week", "week");
    const btn_month = make_btn("Month", "month");

    $btn_group.append(btn_day);
    $btn_group.append(btn_week);
    $btn_group.append(btn_month);

    // Insert before company filter
    const company_filter = report.get_filter("company");
    if (company_filter && company_filter.$wrapper && company_filter.$wrapper.length) {
      $btn_group.insertBefore(company_filter.$wrapper);
    } else {
      (report.page.page_form || report.page.wrapper).append($btn_group);
    }

    // Default to "Day" mode
    setTimeout(() => {
      set_period_mode("day", btn_day);
    }, 100);
  }
};
